package com.thakur.employee.controller; import com.thakur.employee.dto.Requests.*;import com.thakur.employee.model.*;import com.thakur.employee.repository.*;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*; @RestController @RequestMapping("/api/expenses") @RequiredArgsConstructor public class ExpenseController {private final ExpenseRepository repo;private final UserRepository users;@PostMapping Expense create(@Valid @RequestBody ExpenseCreate r,Authentication a){return repo.save(Expense.builder().employee(users.findByEmail(a.getName()).orElseThrow()).category(r.category()).amount(r.amount()).description(r.description()).expenseDate(r.expenseDate()).status(RequestStatus.PENDING).createdAt(LocalDateTime.now()).build());}@GetMapping("/mine") List<Expense> mine(Authentication a){return repo.findByEmployeeEmailOrderByCreatedAtDesc(a.getName());}@GetMapping @PreAuthorize("hasAnyRole('FINANCE','ADMIN')") List<Expense> all(){return repo.findAllByOrderByCreatedAtDesc();}@PatchMapping("/{id}/decision") @PreAuthorize("hasAnyRole('FINANCE','ADMIN')") Expense decide(@PathVariable Long id,@RequestBody Decision d){var x=repo.findById(id).orElseThrow();x.setStatus(RequestStatus.valueOf(d.status().toUpperCase()));x.setFinanceComment(d.comment());return repo.save(x);}}
